class Solution {
public:
    int distinctSubseqII(string s) {
        const int MOD = 1e9 + 7;
        vector<long long> ends_with(26, 0);
        for (char ch : s) {
            int idx = ch - 'a';
            long long sum_all = 0;
            for (int i = 0; i < 26; ++i) sum_all = (sum_all + ends_with[i]) % MOD;
            ends_with[idx] = (sum_all + 1) % MOD;
        }
        long long total = 0;
        for (int i = 0; i < 26; ++i) total = (total + ends_with[i]) % MOD;
        return total;
    }
};

class Solution {
    public int distinctSubseqII(String s) {
        int MOD = 1_000_000_007;
        long[] endsWith = new long[26];
        for (char ch : s.toCharArray()) {
            int idx = ch - 'a';
            long sumAll = 0;
            for (int i = 0; i < 26; i++) sumAll = (sumAll + endsWith[i]) % MOD;
            endsWith[idx] = (sumAll + 1) % MOD;
        }
        long total = 0;
        for (int i = 0; i < 26; i++) total = (total + endsWith[i]) % MOD;
        return (int) total;
    }
}

var distinctSubseqII = function(s) {
    const MOD = 1000000007;
    const endsWith = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97;
        let sumAll = 0;
        for (let j = 0; j < 26; j++) sumAll = (sumAll + endsWith[j]) % MOD;
        endsWith[idx] = (sumAll + 1) % MOD;
    }
    return endsWith.reduce((acc, v) => (acc + v) % MOD, 0);
};
